{"code": "# Define the set S
S = ['a', 'b', 'c', 'd', 'e']

# Define the operation table
operation = {
    'a': {'a': 'a', 'b': 'b', 'c': 'c', 'd': 'b', 'e': 'd'},
    'b': {'a': 'b', 'b': 'c', 'c': 'a', 'd': 'e', 'e': 'c'},
    'c': {'a': 'c', 'b': 'a', 'c': 'b', 'd': 'b', 'e': 'a'},
    'd': {'a': 'b', 'b': 'e', 'c': 'b', 'd': 'e', 'e': 'd'},
    'e': {'a': 'd', 'b': 'b', 'c': 'a', 'd': 'd', 'e': 'c'}
}

# Find all pairs (x, y) where x*y ≠ y*x
non_commutative_pairs = []
elements_involved = set()

for x in S:
    for y in S:
        if operation[x][y] != operation[y][x]:
            non_commutative_pairs.append((x, y))
            elements_involved.add(x)
            elements_involved.add(y)

print("Non-commutative pairs (x, y):")
for pair in non_commutative_pairs:
    x, y = pair
    print(f"{x}*{y} = {operation[x][y]}, {y}*{x} = {operation[y][x]}")

print(f"\nElements involved in non-commutative pairs: {sorted(elements_involved)}")
print(f"Elements involved (alphabetical order): {', '.join(sorted(elements_involved))}")

# Count how many non-commutative pairs we found
print(f"\nTotal non-commutative pairs: {len(non_commutative_pairs)}")

# Also check all pairs to verify our understanding
print("\nChecking all pairs (for verification):")
for x in S:
    for y in S:
        if x != y:  # Skip x=y pairs since they're always commutative in any binary operation
            if operation[x][y] != operation[y][x]:
                print(f"  {x}*{y}={operation[x][y]} ≠ {y}*{x}={operation[y][x]}")"}

